# area: inheritance_mro
# hypothesis: In a diamond hierarchy with cooperative super() calls, the runtime MRO runs each override once in linearized order, so a checker should type Diamond().greet('ann') as str.
from typing import reveal_type


class Base:
    def greet(self, name: str) -> str:
        return 'hi ' + name


class Left(Base):
    def greet(self, name: str) -> str:
        return 'left ' + super().greet(name)


class Right(Base):
    def greet(self, name: str) -> str:
        return 'right ' + super().greet(name)


class Diamond(Left, Right):
    def greet(self, name: str) -> str:
        return 'diamond ' + super().greet(name)


d = Diamond()
reveal_type(d.greet('ann'))
print(d.greet('ann'))
print([k.__name__ for k in Diamond.__mro__])
try:
    d.greet()  # expect-error: greet requires name
except TypeError:
    print('TypeError')
